export const FEEDBACK_CSS = "\n:root{--blue:#004AAD;--blue-2:#0062e0;--navy:#06101f;--navy-2:#0c1a33;--gold:#b8973a;--gold-2:#d8b960;\n--up:#047857;--down:#b45309;--bg:#f3f5fa;--card:#fff;--line:#e6e9f0;--text:#0f172a;--muted:#5b6675;--r:20px;--ease:cubic-bezier(.2,.8,.2,1)}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{font-family:'Montserrat',system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);font-size:14px;line-height:1.55;-webkit-font-smoothing:antialiased}\n.page{max-width:880px;margin:0 auto;padding:16px 16px 84px}\nb,strong{font-weight:600}\n.progress{position:fixed;top:0;left:0;right:0;height:3px;z-index:50;background:linear-gradient(90deg,var(--blue),var(--gold));transform-origin:left;transform:scaleX(var(--p,0))}\n\n/* hero */\n.hero{position:relative;overflow:hidden;isolation:isolate;border-radius:26px;background:linear-gradient(155deg,#0050bd 0%,#003b8e 34%,#0a1f45 68%,var(--navy) 100%);color:#fff;box-shadow:0 24px 60px -28px rgba(0,44,120,.7)}\n.hero-bg{position:absolute;inset:0;z-index:-1;overflow:hidden}\n.hero-bg i{position:absolute;border-radius:50%}\n.hero-bg .b1{width:95%;aspect-ratio:1;left:-35%;top:-55%;background:radial-gradient(circle,rgba(40,130,255,.75) 0%,rgba(0,98,224,.3) 40%,transparent 66%)}\n.hero-bg .b2{width:80%;aspect-ratio:1;right:-30%;bottom:-60%;background:radial-gradient(circle,rgba(0,98,224,.7) 0%,transparent 64%)}\n.hero-bg .b3{width:46%;aspect-ratio:1;right:4%;top:-26%;background:radial-gradient(circle,rgba(184,151,58,.42) 0%,transparent 66%)}\n.hero-bg .mark{position:absolute;right:-7%;bottom:-18%;width:min(62%,360px);opacity:.07}\n.motion .hero-bg .b1{animation:drift1 16s ease-in-out infinite alternate}\n.motion .hero-bg .b2{animation:drift2 21s ease-in-out infinite alternate}\n.motion .hero-bg .b3{animation:drift3 13s ease-in-out infinite alternate}\n@keyframes drift1{to{transform:translate(16%,20%) scale(1.12)}}\n@keyframes drift2{to{transform:translate(-14%,-12%) scale(1.08)}}\n@keyframes drift3{to{transform:translate(-30%,24%) scale(.9)}}\n.hero-in{position:relative;padding:22px 22px 28px}\n.hero-top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:34px}\n.logo{height:46px;width:auto}\n.date{text-align:right;line-height:1.3}\n.date span{display:block;font-size:9.5px;letter-spacing:.22em;text-transform:uppercase;opacity:.6}\n.date b{font-size:12.5px;font-weight:500}\n.eyebrow{font-size:10.5px;letter-spacing:.24em;text-transform:uppercase;font-weight:600;color:var(--gold-2);margin-bottom:12px}\n.hero h1{font-weight:300;font-size:clamp(34px,9vw,56px);letter-spacing:-.025em;line-height:1.04;margin-bottom:10px}\n.w{display:inline-block;overflow:hidden;vertical-align:bottom;padding-bottom:.06em}\n.w>span{display:inline-block}\n.sub{font-size:14px;opacity:.82;max-width:520px}\n.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px}\n.chip{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);padding:6px 12px;border-radius:100px;font-size:11.5px;font-weight:500}\n.motion .w>span{transform:translateY(110%);animation:rise 1s var(--ease) forwards;animation-delay:calc(.12s + var(--i)*.09s)}\n.motion .eyebrow,.motion .sub,.motion .hero-top{opacity:0;animation:fadeUp .9s var(--ease) forwards}\n.motion .eyebrow{animation-delay:.05s}.motion .sub{animation-delay:.45s}.motion .hero-top{animation-delay:.1s}\n.motion .chip{opacity:0;animation:fadeUp .7s var(--ease) forwards;animation-delay:calc(.55s + var(--i)*.06s)}\n@keyframes rise{to{transform:none}}\n@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}\n.motion [data-reveal],.motion .ctx,.motion .steps{opacity:0;transform:translateY(26px);transition:opacity .9s var(--ease),transform .9s var(--ease)}\n.motion [data-reveal].in,.motion .ctx.in,.motion .steps.in{opacity:1;transform:none}\n\n/* menu de seções (grudado no topo) */\n.secnav{position:sticky;top:0;z-index:20;margin:6px -16px 4px;padding:10px 16px;background:rgba(243,245,250,.88);backdrop-filter:saturate(1.6) blur(12px);-webkit-backdrop-filter:saturate(1.6) blur(12px)}\n.sn-track{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch}\n.sn-track::-webkit-scrollbar{display:none}\n.sn-track a{flex:none;padding:8px 14px;border-radius:14px;background:var(--card);border:1px solid var(--line);text-decoration:none;color:var(--muted);font-size:12px;font-weight:600;transition:background .35s,color .35s,border-color .35s;-webkit-tap-highlight-color:transparent}\n.sn-track a.cur{background:var(--navy);border-color:var(--navy);color:#fff}\nsection[id]{scroll-margin-top:70px}\n\n/* KPIs */\n.kpis{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:16px 0}\n.kpi{background:var(--card);border-radius:var(--r);padding:18px 14px;text-align:center;box-shadow:0 1px 2px rgba(6,16,31,.04),0 12px 30px -20px rgba(6,16,31,.22);border-top:3px solid var(--gold)}\n.kpi .v{font-size:32px;font-weight:300;color:var(--blue);line-height:1}\n.kpi .v.up{color:var(--up)}.kpi .v.down{color:var(--down)}\n.kpi .l{font-size:10.5px;text-transform:uppercase;letter-spacing:.14em;color:var(--muted);margin-top:8px;font-weight:600}\n\n/* leitura (ctx) */\n.ctx{position:relative;overflow:hidden;background:var(--card);border-radius:var(--r);padding:22px 22px 22px 26px;margin:16px 0;box-shadow:0 1px 2px rgba(6,16,31,.04),0 10px 30px -18px rgba(6,16,31,.18)}\n.ctx::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(var(--blue),var(--gold))}\n.ctx h4,.steps h4{color:var(--blue);font-size:11px;text-transform:uppercase;letter-spacing:.2em;margin-bottom:12px;font-weight:700}\n.ctx p{font-size:14.5px;line-height:1.75}.ctx p+p{margin-top:10px}\n.hl{font-weight:600;background-image:linear-gradient(rgba(184,151,58,.34),rgba(184,151,58,.34));background-repeat:no-repeat;background-position:0 88%;background-size:100% 40%;padding:0 2px}\n\n/* seções */\n.sec{background:var(--card);border-radius:var(--r);padding:22px 18px;margin:16px 0;box-shadow:0 1px 2px rgba(6,16,31,.04),0 10px 30px -18px rgba(6,16,31,.18)}\n.sec h3{font-size:11px;text-transform:uppercase;letter-spacing:.2em;color:var(--blue);font-weight:700;margin-bottom:14px}\n.lead{font-size:13px;color:var(--muted);margin:-4px 0 14px}\n.note{font-size:11.5px;color:var(--muted);margin-top:12px;line-height:1.6}\n.comment{font-size:14px;line-height:1.75;margin-top:14px}.comment p+p{margin-top:9px}\n\n/* galeria: faixa que desliza no celular */\n.gal+.gal{margin-top:18px}\n.gal-h{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}\n.gal-h h4{font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--navy)}\n.hint{font-size:10.5px;color:var(--muted)}\n.track{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none;margin:0 -18px;padding:0 18px 4px}\n.track::-webkit-scrollbar{display:none}\n.ph{position:relative;margin:0;flex:none;width:62%;max-width:300px;scroll-snap-align:center;border-radius:16px;overflow:hidden;background:#eef1f7;aspect-ratio:3/4;cursor:zoom-in;-webkit-tap-highlight-color:transparent}\n.ph img{width:100%;height:100%;object-fit:cover;display:block}\n.ph figcaption{position:absolute;left:8px;top:8px;background:rgba(6,16,31,.78);color:#fff;font-size:11px;font-weight:600;letter-spacing:.06em;padding:4px 10px;border-radius:100px}\n.ph.empty{display:flex;align-items:center;justify-content:center;cursor:default}\n.ph.empty span{font-size:12px;color:var(--muted)}\n\n/* antes e agora */\n.pairs{display:grid;gap:18px}\n.pair-legend{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.pair-legend span{text-align:center;background:var(--navy);color:#fff;font-size:11px;font-weight:600;letter-spacing:.08em;padding:7px;border-radius:10px}\n.pair h4{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--blue);font-weight:700;margin-bottom:6px}\n.pair-in{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.pair-in .ph{width:100%;max-width:none;scroll-snap-align:none}\n.pair-in .ph figcaption{display:none}\n\n/* tabela de medidas */\ntable.med{width:100%;border-collapse:collapse}\ntable.med thead th{background:var(--navy);color:#fff;font-size:10px;letter-spacing:.1em;text-transform:uppercase;font-weight:600;padding:10px 8px;text-align:right}\ntable.med thead th:first-child{text-align:left;border-radius:12px 0 0 0;padding-left:12px}\ntable.med thead th:last-child{border-radius:0 12px 0 0}\ntable.med td{padding:11px 8px;border-bottom:1px solid #eef1f7;font-size:13px;text-align:right}\ntable.med td.lbl{text-align:left;font-weight:600;color:var(--navy);padding-left:12px}\ntable.med tr:last-child td{border-bottom:none}\n.delta{font-weight:700}\ntable.med .delta.up{color:var(--up)}table.med .delta.down{color:var(--down)}table.med .delta.flat{color:var(--muted)}\n\n/* leitura e próximos passos */\n.read p{font-size:14.5px;line-height:1.75}.read p+p{margin-top:11px}\n.read b{color:var(--navy)}\n.steps{background:#f2f6ff;border:1px solid #d6e1f5;border-radius:var(--r);padding:20px 20px;margin:16px 0}\n.steps ul{list-style:none;display:grid;gap:10px}\n.steps li{position:relative;padding-left:26px;font-size:14px;line-height:1.65}\n.steps li::before{content:\"\";position:absolute;left:2px;top:.5em;width:9px;height:9px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--gold))}\n.steps b{color:var(--navy)}\n.internal{background:#fff7ed;border:1px solid #fdba74;border-radius:14px;padding:10px 14px;margin:16px 0 0;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#9a3412;text-align:center}\n\n/* fecho */\n.closing{text-align:center;padding:40px 8px 18px}\n.closing blockquote{font-size:clamp(21px,5.4vw,30px);font-weight:300;line-height:1.38;color:var(--navy);max-width:640px;margin:0 auto;letter-spacing:-.01em}\n.qw{display:inline-block}\n.motion .closing .qw{opacity:0;transform:translateY(12px);transition:opacity .7s var(--ease),transform .7s var(--ease);transition-delay:calc(.2s + var(--i)*55ms)}\n.motion .closing.in .qw{opacity:1;transform:none}\n.motion .closing[data-reveal]{transform:none}\n.sign{margin-top:18px;font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);font-weight:700}\n.foot{font-size:11px;color:var(--muted);text-align:center;margin-top:18px;line-height:1.6}\n.fab{position:fixed;right:16px;bottom:16px;z-index:40;display:flex;align-items:center;gap:8px;background:var(--blue);color:#fff;border:0;border-radius:100px;padding:13px 20px;font:600 13px 'Montserrat',system-ui,sans-serif;cursor:pointer;box-shadow:0 12px 26px -10px rgba(0,74,173,.75)}\n.fab svg{width:17px;height:17px;fill:none;stroke:#fff;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}\n.embed .fab,.embed .progress{display:none}\n\n/* ampliar foto */\n.lb{position:fixed;inset:0;z-index:100;background:rgba(6,16,31,.94);display:none;align-items:center;justify-content:center;flex-direction:column;padding:16px;gap:12px}\n.lb.on{display:flex}\n.lb img{max-width:100%;max-height:82vh;border-radius:14px;object-fit:contain}\n.lb span{color:#fff;font-size:12px;letter-spacing:.12em;text-transform:uppercase;font-weight:600}\n.lb button{position:absolute;top:14px;right:14px;width:42px;height:42px;border-radius:50%;border:0;background:rgba(255,255,255,.14);color:#fff;font-size:22px;line-height:1;cursor:pointer}\n\n@media (min-width:640px){\n  .page{padding:28px 24px 96px}\n  .hero-in{padding:30px 38px 38px}\n  .hero-top{margin-bottom:44px}\n  .logo{height:54px}\n  .kpis{grid-template-columns:repeat(4,1fr)}\n  .secnav{margin:6px 0 4px;padding:10px 0}\n  .sec{padding:26px 28px}\n  .track{margin:0 -28px;padding:0 28px 4px}\n  .ph{width:34%}\n  .pair-in .ph{width:100%}\n  .pairs{grid-template-columns:repeat(3,1fr)}\n  .pair-legend{grid-column:1/-1}\n  .pair-in{grid-template-columns:1fr}\n}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}html{scroll-behavior:auto}}\n\n@media print{\n  @page{size:A4;margin:10mm 8mm 12mm}\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact;animation:none!important;transition:none!important}\n  html{scroll-behavior:auto}\n  body{background:#fff;font-size:11.5px}\n  .page{max-width:none;padding:0}\n  .progress,.fab,.secnav,.hint,.lb,.hero-bg .mark{display:none!important}\n  [data-reveal],.ctx,.steps,.qw,.w>span,.chip,.eyebrow,.sub,.hero-top{opacity:1!important;transform:none!important}\n  .hero{box-shadow:none;border-radius:16px}\n  .hero-in{padding:22px 28px 24px}\n  .hero-top{margin-bottom:18px}\n  .hero h1{font-size:34px}\n  .kpis{grid-template-columns:repeat(4,1fr)}\n  .kpi,.sec,.ctx,.steps{box-shadow:none}\n  .sec{border:1px solid #e3e7ee;padding:16px 18px}\n  .kpi,.ctx,.steps,.closing,.read p,.note,table.med tr,.pair,.med-sec{break-inside:avoid;page-break-inside:avoid}\n  h3,h4{break-after:avoid;page-break-after:avoid}\n  /* sequência: grade de 4 por linha, cada ângulo em seu bloco */\n  .photo-sec{break-before:page;page-break-before:always}\n  .gal{break-inside:auto}\n  .gal+.gal{break-before:page;page-break-before:always}\n  .track{display:flex;flex-wrap:wrap;overflow:visible;margin:0;padding:0;gap:6px}\n  .ph{width:calc(25% - 5px);max-width:none;border-radius:8px;cursor:default}\n  .ph figcaption{font-size:9px;padding:3px 7px}\n  /* antes e agora: uma página de fotos e uma de medidas */\n  .impact{break-before:page;page-break-before:always;border-top:5px solid var(--gold)}\n  .impact-measures-only{break-after:page;page-break-after:always}\n  .pairs{grid-template-columns:repeat(3,1fr);gap:10px}\n  .pair-in{grid-template-columns:1fr;gap:8px}\n  .pair-in .ph{width:100%;aspect-ratio:3/4}\n  .comment{font-size:12.5px}\n  table.med thead{display:table-header-group}\n  table.med td{padding:6px 8px;font-size:11.5px}\n  .closing{padding:16px 0 4px}\n  .closing blockquote{font-size:20px}\n}\n\n/* ---------- gráficos e extras ---------- */\n.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0 4px}\n.stats>div{background:var(--card);border-radius:16px;padding:12px 8px;text-align:center;box-shadow:0 1px 2px rgba(6,16,31,.04),0 10px 24px -18px rgba(6,16,31,.2)}\n.stats b{display:block;font-size:26px;font-weight:300;color:var(--blue);line-height:1.1}\n.stats span{font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600;line-height:1.3;display:block;margin-top:4px}\n.dest{display:grid;gap:10px;margin:16px 0}\n.dst{position:relative;background:var(--card);border-radius:var(--r);padding:16px 18px 16px 22px;box-shadow:0 1px 2px rgba(6,16,31,.04),0 10px 26px -18px rgba(6,16,31,.2);overflow:hidden}\n.dst::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--up)}\n.dst.flat::before{background:var(--blue)}.dst.warn::before{background:var(--gold)}\n.dk{display:block;font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:var(--muted)}\n.dst b{display:block;font-size:17px;font-weight:600;color:var(--navy);margin:3px 0 4px}\n.dst p{font-size:13.5px;color:var(--muted);line-height:1.6}\n.evol>h4,.evol .bars h4,.evol .tline h4,.peso h4{font-size:11px;text-transform:uppercase;letter-spacing:.16em;color:var(--navy);font-weight:700;margin:22px 0 10px}\n.evol>h3+.tline h4{margin-top:0}\n.tline{margin-bottom:6px}\n.tl-r{display:grid;grid-template-columns:54px 1fr;align-items:center;gap:8px;margin:7px 0}\n.tl-r>span{font-size:10.5px;color:var(--muted);font-weight:600}\n.tl-t{position:relative;height:16px;border-radius:8px;background:#eef1f7}\n.tl-t i{position:absolute;top:50%;width:11px;height:11px;margin:-5.5px 0 0 -5.5px;border-radius:50%}\n.tl-t i.df{background:var(--blue)}.tl-t i.dm{background:var(--gold)}\n.tl-m{position:relative;height:18px;margin:2px 0 0 62px}\n.tl-m .tk{position:absolute;top:0;width:1px;height:6px;background:#c8d2e3}\n.tl-m .tk em{position:absolute;top:7px;left:-10px;font-style:normal;font-size:9.5px;color:var(--muted);letter-spacing:.06em}\n.tl-e{display:flex;justify-content:space-between;margin:6px 0 0 62px;font-size:11px;font-weight:600;color:var(--navy)}\n.bars .note{margin-top:10px}\n.bar-r{display:grid;grid-template-columns:96px 1fr 38px;align-items:center;gap:8px;padding:5px 0}\n.bl{font-size:12.5px;font-weight:600;color:var(--navy)}\n.bt{position:relative;height:14px;background:#f1f4f9;border-radius:8px;overflow:hidden}\n.bz{position:absolute;left:50%;top:0;bottom:0;width:1.5px;background:#c8d2e3;z-index:1}\n.bb{position:absolute;top:2px;bottom:2px;border-radius:6px}\n.bb.up{background:linear-gradient(90deg,#34b37f,var(--up))}.bb.down{background:linear-gradient(90deg,#e0a24a,var(--down))}.bb.flat{background:#c8d2e3}\n.motion .bb{transform:scaleX(0);transition:transform 1.1s var(--ease) .2s}\n.motion .evol.in .bb{transform:scaleX(1)}\n.motion .bb[style*=\"left:50%\"]{transform-origin:left}.motion .bb[style*=\"right:50%\"]{transform-origin:right}\n.bv{font-size:12.5px;font-weight:700;text-align:right}\n.bv.up{color:var(--up)}.bv.down{color:var(--down)}.bv.flat{color:var(--muted)}\n.sparks{display:grid;grid-template-columns:1fr;gap:12px;margin-top:6px}\n.spk{background:#f7f9fd;border:1px solid #e8edf6;border-radius:18px;padding:14px 14px 10px;color:var(--blue)}\n.spk.up{color:var(--up)}.spk.down{color:var(--down)}.spk.flat{color:var(--blue)}\n.spk-h{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.spk-h b{font-size:13px;font-weight:600;color:var(--navy)}\n.chip-d{font-size:11.5px;font-weight:700;padding:3px 9px;border-radius:100px;background:#e7f5ee;color:var(--up)}\n.chip-d.down{background:#fdf0dd;color:var(--down)}.chip-d.flat{background:#eaeef6;color:var(--muted)}\n.spk-v{font-size:30px;font-weight:300;line-height:1.1;margin-top:4px;color:var(--navy)}\n.spk-v small{font-size:13px;color:var(--muted)}\n.spk svg{width:100%;height:auto;display:block;margin-top:2px;overflow:visible}\n.spk .ln{fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n.spk .ar{stroke:none;color:inherit}\n.spk .pt{fill:#fff;stroke:currentColor;stroke-width:1.8}\n.spk .pt-end{fill:currentColor;stroke:#fff;stroke-width:2}\n.spk .sv-l{font-size:11px;font-weight:600;fill:var(--muted);font-family:inherit}\n.spk .sv-e{fill:var(--navy)}\n.spk-f{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;color:var(--muted);flex-wrap:wrap}\n.spk-warn{background:#fff3df;color:#9a5a00;border-radius:100px;padding:2px 9px;font-size:10px;font-weight:600}\n.motion .spk .ln{stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 1.6s var(--ease) .2s}\n.motion .evol.in .spk .ln{stroke-dashoffset:0}\n.motion .spk .ln[stroke-dasharray]{stroke-dasharray:4 4;stroke-dashoffset:0}\n.rcq{display:flex;gap:14px;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#f2f6ff,#fff);border:1px solid #d6e1f5;border-radius:18px;padding:16px 18px;margin-top:14px;flex-wrap:wrap}\n.rl{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:700}\n.rv{font-size:28px;font-weight:300;color:var(--navy);margin-top:2px}\n.rv i{font-style:normal;color:var(--muted);margin:0 4px}.rv b{font-weight:600;color:var(--up)}\n.rcq.down .rv b{color:var(--down)}.rcq.flat .rv b{color:var(--blue)}\n.rcq p{font-size:12.5px;color:var(--muted);flex:1 1 200px;line-height:1.55}\n.peso{margin-top:6px}\n.peso .spk{max-width:420px}\n.cmp-btn{margin-top:10px;width:100%;border:1px solid var(--line);background:#f6f8fc;color:var(--blue);border-radius:12px;padding:10px;font:600 12px 'Montserrat',system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.cmp{display:none;position:relative;margin-top:10px;border-radius:16px;overflow:hidden;aspect-ratio:3/4;background:#eef1f7;touch-action:pan-y;user-select:none;-webkit-user-select:none}\n.pair.cmp-on .cmp{display:block}.pair.cmp-on .pair-in{display:none}\n.cmp img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none}\n.cmp .top{clip-path:inset(0 calc(100% - var(--x,50%)) 0 0)}\n.cmp .bar{position:absolute;top:0;bottom:0;left:var(--x,50%);width:3px;margin-left:-1.5px;background:#fff;box-shadow:0 0 12px rgba(0,0,0,.4)}\n.cmp .bar::after{content:\"\\2194\";position:absolute;top:50%;left:50%;width:38px;height:38px;margin:-19px 0 0 -19px;border-radius:50%;background:#fff;color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700;box-shadow:0 4px 14px rgba(0,0,0,.35)}\n.cmp .tg{position:absolute;top:10px;background:rgba(6,16,31,.78);color:#fff;font-size:11px;font-weight:600;padding:4px 10px;border-radius:100px}\n.cmp .tg.l{left:10px}.cmp .tg.r{right:10px}\n.cmp input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize;margin:0}\n@media (min-width:640px){\n  .sparks{grid-template-columns:repeat(2,1fr)}\n  .stats b{font-size:30px}\n  .dest{grid-template-columns:repeat(3,1fr)}\n  .bar-r{grid-template-columns:130px 1fr 44px}\n}\n@media (min-width:900px){.sparks{grid-template-columns:repeat(3,1fr)}}\n@media print{\n  .cmp-btn,.cmp{display:none!important}\n  .stats>div,.dst,.spk,.rcq{box-shadow:none}\n  .dest{grid-template-columns:repeat(3,1fr)}\n  .dst,.spk,.rcq,.bar-r,.tline,.peso{break-inside:avoid;page-break-inside:avoid}\n  .evol{break-before:page;page-break-before:always}\n  .sparks{grid-template-columns:repeat(3,1fr);gap:8px}\n  .spk{padding:8px 9px 6px}.spk-v{font-size:20px}.spk-h b{font-size:11px}\n  .bar-r{grid-template-columns:110px 1fr 40px;padding:3px 0}\n  .bb{transform:none!important}\n  .spk .ln{stroke-dashoffset:0!important}\n}\n\n/* leitura: veredito + blocos */\n.verdict{position:relative;background:linear-gradient(135deg,#0a1f45,#003b8e);color:#fff;border-radius:18px;padding:20px 20px 18px;margin:0 0 18px;overflow:hidden}\n.verdict::after{content:\"\";position:absolute;right:-50px;top:-60px;width:180px;height:180px;border-radius:50%;background:radial-gradient(circle,rgba(216,185,96,.45),transparent 68%)}\n.verdict .vk{position:relative;display:block;font-size:10px;letter-spacing:.22em;text-transform:uppercase;font-weight:700;color:var(--gold-2);margin-bottom:6px}\n.read .verdict b,.verdict b{color:#fff;position:relative;display:block;font-size:24px;font-weight:300;line-height:1.2;margin-bottom:8px}\n.verdict p{position:relative;font-size:14.5px;line-height:1.7;opacity:.92}\n.rb{padding:14px 0;border-top:1px solid #eef1f7}\n.rb:first-of-type{border-top:0;padding-top:0}\n.rb h5{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--blue);font-weight:700;margin-bottom:6px}\n.rb p{font-size:14.5px;line-height:1.75;margin:0}\n.rb:last-child{background:#f2f6ff;border:1px solid #d6e1f5;border-radius:16px;padding:14px 16px;margin-top:10px}\n.rb:last-child h5{color:var(--navy)}\n@media print{.verdict{break-inside:avoid;page-break-inside:avoid}.rb{break-inside:avoid;page-break-inside:avoid}.rb p{font-size:12px}}\n";

export const FEEDBACK_HEAD_JS = "(function(h){var e=false;try{e=window.self!==window.top}catch(x){e=true}if(e)h.classList.add('embed');var rm=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;if(!rm&&!window.__PDF__&&!navigator.webdriver)h.classList.add('motion')})(document.documentElement);";

export const FEEDBACK_JS = "\n(function(){\nvar d=document,h=d.documentElement;\nfunction $(s,r){return Array.prototype.slice.call((r||d).querySelectorAll(s))}\nvar REVEAL='[data-reveal],.ctx,.steps';\nif(h.classList.contains('motion')&&'IntersectionObserver' in window){\n  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:0,rootMargin:'0px 0px -10% 0px'});\n  $(REVEAL).forEach(function(el){io.observe(el)});\n}else{$(REVEAL).forEach(function(el){el.classList.add('in')})}\n\n/* menu de seções: rola até a seção e acende a que está na tela */\n$('.sn-track a').forEach(function(a){a.addEventListener('click',function(e){\n  var t=d.getElementById(a.getAttribute('href').slice(1));if(!t)return;e.preventDefault();\n  t.scrollIntoView({behavior:h.classList.contains('motion')?'smooth':'auto',block:'start'})})});\nif('IntersectionObserver' in window){\n  var spy=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;\n    $('.sn-track a').forEach(function(a){a.classList.toggle('cur',a.getAttribute('href')==='#'+e.target.id)});\n    var c=d.querySelector('.sn-track a.cur');if(c){var tr=c.parentNode;tr.scrollTo({left:c.offsetLeft-tr.clientWidth/2+c.clientWidth/2,behavior:'smooth'})}})},{rootMargin:'-30% 0px -60% 0px'});\n  $('section[id]').forEach(function(s){spy.observe(s)});\n}\n\n/* ampliar foto com um toque */\nvar lb=d.querySelector('.lb');\nif(lb){var li=lb.querySelector('img'),lc=lb.querySelector('span');\n  $('.ph:not(.empty)').forEach(function(f){f.addEventListener('click',function(){li.src=f.querySelector('img').src;lc.textContent=f.dataset.cap||'';lb.classList.add('on')})});\n  lb.addEventListener('click',function(){lb.classList.remove('on')});\n  d.addEventListener('keydown',function(e){if(e.key==='Escape')lb.classList.remove('on')});\n}\n\n/* barra de progresso de leitura */\nvar pb=d.querySelector('.progress');\nif(pb){var tk=false;window.addEventListener('scroll',function(){if(tk)return;tk=true;requestAnimationFrame(function(){tk=false;\n  var mx=h.scrollHeight-window.innerHeight;pb.style.setProperty('--p',mx>0?Math.min(window.pageYOffset/mx,1):0)})},{passive:true})}\n\nvar fab=d.querySelector('.fab');if(fab)fab.addEventListener('click',function(){window.print()});\nwindow.addEventListener('beforeprint',function(){$(REVEAL).forEach(function(el){el.classList.add('in')})});\n})();\n\n(function(){\nvar d=document;\nfunction $(s,r){return Array.prototype.slice.call((r||d).querySelectorAll(s))}\n/* comparador de fotos: arrasta para revelar antes/agora (usa as mesmas imagens da página) */\n$('.pair').forEach(function(p){\n  var f=$('.ph img',p);if(f.length<2)return;\n  var cap=$('.ph',p).map(function(x){return (x.dataset.cap||'').split('·').pop().trim()});\n  var b=d.createElement('button');b.type='button';b.className='cmp-btn';b.textContent='Comparar deslizando';\n  var c=d.createElement('div');c.className='cmp';\n  c.innerHTML='<img alt=\"\"><img class=\"top\" alt=\"\"><i class=\"bar\"></i><span class=\"tg l\"></span><span class=\"tg r\"></span><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"Comparar antes e agora\">';\n  var im=$('img',c);im[0].src=f[1].src;im[1].src=f[0].src;\n  $('.tg.l',c)[0].textContent='Antes · '+cap[0];$('.tg.r',c)[0].textContent='Agora · '+cap[1];\n  var r=$('input',c)[0];r.addEventListener('input',function(){c.style.setProperty('--x',r.value+'%')});\n  b.addEventListener('click',function(){var on=p.classList.toggle('cmp-on');b.textContent=on?'Voltar para lado a lado':'Comparar deslizando'});\n  p.appendChild(b);p.appendChild(c);\n});\n})();\n";

